// Temporary passwords for staff (route POST /admin/staff and POST /admin/staff/:id/password): generated by the server,
// shown once, from an alphabet without look-alike characters. Pure: the random source is a parameter, so it is unit-tested.
import { checkPasswordPolicy } from './password-policy';

const UPPER = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
const LOWER = 'abcdefghijkmnopqrstuvwxyz';
const DIGITS = '23456789';
const ALPHABET = UPPER + LOWER + DIGITS;

/** How many characters a temporary password has (the console's mock uses 14 too). */
export const TEMPORARY_PASSWORD_LENGTH = 14;

/**
 * Makes one temporary password.
 *
 * Why: the owner hands it to the member by a safe channel; it must be easy to read aloud (no `I`, `l`, `O`, `0`, `1`) and
 * contain upper case, lower case and digits so it passes the password policy.
 *
 * @param pick returns a uniformly random whole number from 0 up to but not including `max` (a cryptographic source)
 * @returns the password
 */
export function generateTemporaryPassword(pick: (max: number) => number): string {
  const characters = [
    UPPER[pick(UPPER.length)]!,
    LOWER[pick(LOWER.length)]!,
    DIGITS[pick(DIGITS.length)]!,
    ...Array.from({ length: TEMPORARY_PASSWORD_LENGTH - 3 }, () => ALPHABET[pick(ALPHABET.length)]!),
  ];
  // Fisher-Yates, so the three guaranteed characters are not always first.
  for (let i = characters.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [characters[i], characters[j]] = [characters[j]!, characters[i]!];
  }
  return characters.join('');
}

/**
 * Makes a temporary password that the staff password policy accepts for this account.
 *
 * Why: the member must be able to keep using it until the forced change, and a random string could (very rarely) contain the
 * email name or the person's name.
 *
 * @param pick the random source of {@link generateTemporaryPassword}
 * @param account the email and name the password must not contain
 * @returns the password
 * @throws {Error} when ten tries in a row fail the policy (a broken random source)
 */
export function temporaryPasswordFor(
  pick: (max: number) => number,
  account: { readonly email: string; readonly name: string },
): string {
  for (let attempt = 0; attempt < 10; attempt++) {
    const candidate = generateTemporaryPassword(pick);
    if (!checkPasswordPolicy(candidate, account)) return candidate;
  }
  throw new Error('Could not generate a temporary password that passes the password policy.');
}
